import sys

def is_correct(s):
    balance = 0
    for c in s:
        if c == '(':
            balance += 1
        elif c == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    s = input[1]

    open_needed = 0
    close_needed = 0
    result = []

    for c in s:
        if c == '(':
            open_needed += 1
        elif c == ')':
            close_needed += 1
        else:
            if open_needed > close_needed:
                result.append(')')
                close_needed += 1
            else:
                result.append('(')
                open_needed += 1

    if open_needed != close_needed or not is_correct(result):
        print(":(")
    else:
        print("".join(result))

main()
